const updateIncidentFacts = `-- name: UpdateIncidentFacts :execrows
UPDATE breach.incidents SET title = $1, description = $2, breach_types = $3, incident_type = $4,
    occurred_at = $5, aware_at = $6, pdpc_due_at = $7, contained_at = $8,
    affected_subjects = $9, affected_categories = $10, owner_user_id = $11,
    updated_at = now(), updated_by = $12, row_version = row_version + 1
WHERE id = $13 AND row_version = $14
`

type UpdateIncidentFactsParams struct {
	Title              string             `db:"title" json:"title"`
	Description        string             `db:"description" json:"description"`
	BreachTypes        []string           `db:"breach_types" json:"breach_types"`
	IncidentType       *string            `db:"incident_type" json:"incident_type"`
	OccurredAt         pgtype.Timestamptz `db:"occurred_at" json:"occurred_at"`
	AwareAt            pgtype.Timestamptz `db:"aware_at" json:"aware_at"`
	PdpcDueAt          pgtype.Timestamptz `db:"pdpc_due_at" json:"pdpc_due_at"`
	ContainedAt        pgtype.Timestamptz `db:"contained_at" json:"contained_at"`
	AffectedSubjects   *int32             `db:"affected_subjects" json:"affected_subjects"`
	AffectedCategories []uuid.UUID        `db:"affected_categories" json:"affected_categories"`
	OwnerUserID        pgtype.UUID        `db:"owner_user_id" json:"owner_user_id"`
	Actor              pgtype.UUID        `db:"actor" json:"actor"`
	ID                 uuid.UUID          `db:"id" json:"id"`
	RowVersion         int32              `db:"row_version" json:"row_version"`
}

func (q *Queries) UpdateIncidentFacts(ctx context.Context, arg UpdateIncidentFactsParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateIncidentFacts,
		arg.Title,
		arg.Description,
		arg.BreachTypes,
		arg.IncidentType,
		arg.OccurredAt,
		arg.AwareAt,
		arg.PdpcDueAt,
		arg.ContainedAt,
		arg.AffectedSubjects,
		arg.AffectedCategories,
		arg.OwnerUserID,
		arg.Actor,
		arg.ID,
		arg.RowVersion,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
